L000228	
L000229	This Supplemental Material provides additional information on the two-photon Dicke model. In Sec.~\ref{sec:MeanFieldSqueezedStates}, we introduce the mean-field approximation using squeezed vacuum states, providing a classical limit for the system. The critical points of the equations of motion derived from this classical limit yield analytic expressions for the ground-state energy, the number of photons, and atomic inversion in both the normal and superradiant phases. In Sec.~\ref{sec:CollapseSuperradiantPhase}, we present further evidence regarding the disappearance of the superradiant phase, including the case of null atomic frequency. Section~\ref{sec:ThermodynamicLimitSqueezedStates} discusses the thermodynamic limit of the mean-field approximation with squeezed vacuum states, which helps us to detect the classical signature of the spectral collapse. Finally, in Sec.~\ref{sec:MeanFieldCoherentStates}, we perform a mean-field approximation using coherent states and describe the classical signature of the spectral collapse using this approach.
L000230	
L000231	
L000232	\section{Mean-field approximation with squeezed vacuum states}
L000233	\label{sec:MeanFieldSqueezedStates}
L000234	
L000235	
L000236	Inspired by the results of the ground state of the two-photon Dicke Hamiltonian presented in Ref.~\cite{Garbe2017}, we introduce a mean-field approximation to define a classical phase space using squeezed vacuum states $|\xi\rangle$ for the bosonic sector
L000237	\begin{equation}
L000238	    |\xi\rangle = e^{(\xi^{\ast}\hat{a}^{2}-\xi\hat{a}^{\dagger2})/2}|0\rangle ,
L000239	\end{equation}
L000240	and Bloch coherent states $|\beta\rangle$ for the atomic sector
L000241	\begin{equation}
L000242	    \label{eq:BlochState}
L000243	    |\beta\rangle = \frac{1}{(1+|\beta|^{2})^{j}}e^{\beta\hat{J}_{+}}|j,-j\rangle
L000244	\end{equation}
L000245	with complex parameter
L000246	\begin{equation}
L000247	    \label{eq:AtomicParameter}
L000248	    \beta = \frac{Q+iP}{\sqrt{4-Q^{2}-P^{2}}} ,
L000249	\end{equation}
L000250	where $(Q,P)$ are the atomic classical variables of phase space. In the above expressions, $|0\rangle$ is the bosonic vacuum state and $|j,-j\rangle$ is the atomic state with all atoms in the ground state. The squeezing parameter $\xi = r e^{i\theta}\in\mathbb{C}$ is a complex number with magnitude $r$ and phase $\theta$. It provides a connection with bosonic classical variables $(q,p)$ using the transformation $q=\sqrt{2/j}\sinh(r)\cos(\theta)$ and $p=\sqrt{2/j}\sinh(r)\sin(\theta)$
L000251	\begin{align}
L000252	    \langle\xi|\hat{a}|\xi\rangle = & \langle\xi|\hat{a}^{\dagger}|\xi\rangle = 0, \\
L000253	    \langle\xi|\hat{a}^{2}|\xi\rangle = & \langle\xi|\hat{a}^{\dagger2}|\xi\rangle^{\ast} = -e^{i\theta}\sinh(r)\cosh(r) = -\sqrt{\frac{j}{2}\left(1+\frac{j}{2}\left(q^{2}+p^{2}\right)\right)}(q+ip) , \\
L000254	    \langle\xi|\hat{a}^{\dagger}\hat{a}|\xi\rangle = & \sinh^{2}(r) = \frac{j}{2}\left(q^{2}+p^{2}\right) .
L000255	\end{align}
L000256	
L000257	The expectation value of the quantum Hamiltonian $\hat{H}_{\text{D}}$ [Eq.~(1) in the main text] under squeezed vacuum states $|\mathbf{x}\rangle \equiv |\xi\rangle\otimes|\beta\rangle$, where $\mathbf{x}=(q,p;Q,P)$, provides a classical limit of the two-photon Dicke model
L000258	\begin{align}
L000259	    \label{eq:DickeSqueezedStates}
L000260	    h_{\text{D}}(\mathbf{x}) = & \frac{1}{j}\langle\mathbf{x}|\hat{H}_{\text{D}}|\mathbf{x}\rangle = \frac{1}{j}\langle\beta|\otimes\langle\xi|\hat{H}_{\text{D}}|\xi\rangle\otimes|\beta\rangle \nonumber \\
L000261	    = & \frac{1}{j}\left\{\omega \langle\xi|\hat{a}^{\dagger}\hat{a}|\xi\rangle - j\omega_{0} \frac{1-|\beta|^{2}}{1+|\beta|^{2}} + \gamma \left[ \langle\xi|\hat{a}^{\dagger2}|\xi\rangle + \langle\xi|\hat{a}^{2}|\xi\rangle \right] \frac{\beta+\beta^{\ast}}{1+|\beta|^{2}}\right\}\nonumber \\
L000262	    = & \frac{1}{j}\left\{\omega \sinh^{2}(r) + j\omega_{0}\left(\frac{Q^{2}+P^{2}}{2}-1\right)  - 2\gamma\sinh(r)\cosh(r)\cos(\theta) Q\sqrt{1-\frac{Q^{2}+P^{2}}{4}} \right\}  \nonumber
L000263	    \\
L000264	    = & \frac{\omega}{2}\left(q^{2}+p^{2}\right) + \omega_{0}\left(\frac{Q^{2}+P^{2}}{2}-1\right) - 2\gamma qQ\sqrt{\left(\frac{1}{2j}+\frac{q^{2}+p^{2}}{4}\right)\left(1-\frac{Q^{2}+P^{2}}{4}\right)} ,
L000265	\end{align}
L000266	where the energy shells $\epsilon=E/j$ are scaled to the system size $j$.
L000267	
L000268	The Hamilton's equations of motion of the Hamiltonian presented in Eq.~\eqref{eq:DickeSqueezedStates} are given by
L000269	\begin{align}
L000270	    \dot{q} = & \frac{\partial h_{\text{D}}(\mathbf{x})}{\partial p} = \omega p - \frac{\gamma qpQ}{2}\sqrt{1-\frac{Q^{2} + P^{2}}{4}}\left(\frac{1}{2j}+\frac{q^{2}+p^{2}}{4}\right)^{-1/2} , \\
L000271	    \dot{p} = & -\frac{\partial h_{\text{D}}(\mathbf{x})}{\partial q} = - \omega q + 2\gamma Q\sqrt{1-\frac{Q^{2} + P^{2}}{4}}\left(\frac{1}{2j}+\frac{2q^{2}+p^{2}}{4}\right)\left(\frac{1}{2j}+\frac{q^{2}+p^{2}}{4}\right)^{-1/2} , \\
L000272	    \dot{Q} = & \frac{\partial h_{\text{D}}(\mathbf{x})}{\partial P} = \omega_{0}P + \frac{\gamma qQP}{2}\sqrt{\frac{1}{2j}+\frac{q^{2}+p^{2}}{4}}\left(1-\frac{Q^{2} + P^{2}}{2}\right)^{-1/2} , \\
L000273	    \dot{P} = & -\frac{\partial h_{\text{D}}(\mathbf{x})}{\partial Q} = -\omega_{0}Q + 2\gamma q\sqrt{\frac{1}{2j}+\frac{q^{2}+p^{2}}{4}}\left(1-\frac{2Q^{2} + P^{2}}{4}\right)\left(1-\frac{Q^{2} + P^{2}}{4}\right)^{-1/2} .
L000274	\end{align}
L000275	The minimization of the last set of equations $\dot{q}=\dot{p}=\dot{Q}=\dot{P}=0$ provides the critical points
L000276	\begin{align}
L000277	    \label{eq:ExtremeValuesNP}
L000278	    \mathbf{x}_{0} = & (0,0;0,0)  \hspace{0.5in} \text{for (NP)}, \\
L000279	    \label{eq:ExtremeValuesSPp}
L000280	    \mathbf{x}_{+} = & \left(\pm\frac{1}{\sqrt{j}}\left(\sqrt{\frac{1-\frac{4\gamma^{2}}{\omega^{2}}}{1-\frac{j^{2}\omega_{0}^{2}}{\gamma^{2}}}}-1\right)^{1/2},0;+\left(2-\frac{j\omega_{0}\omega}{\gamma^{2}}\sqrt{\frac{1-\frac{4\gamma^{2}}{\omega^{2}}}{1-\frac{j^{2}\omega_{0}^{2}}{\gamma^{2}}}}\right)^{1/2},0\right) \hspace{0.5in} \text{for (SP)}, \\
L000281	    \label{eq:ExtremeValuesSPm}
L000282	    \mathbf{x}_{-} = & \left(\pm\frac{1}{\sqrt{j}}\left(\sqrt{\frac{1-\frac{4\gamma^{2}}{\omega^{2}}}{1-\frac{j^{2}\omega_{0}^{2}}{\gamma^{2}}}}-1\right)^{1/2},0;-\left(2-\frac{j\omega_{0}\omega}{\gamma^{2}}\sqrt{\frac{1-\frac{4\gamma^{2}}{\omega^{2}}}{1-\frac{j^{2}\omega_{0}^{2}}{\gamma^{2}}}}\right)^{1/2},0\right) \hspace{0.5in} \text{for (SP)},
L000283	\end{align}
L000284	where the solution $\mathbf{x}_{0}\in\mathbb{R}$ belongs to the normal phase (NP) and the solutions $\mathbf{x}_{\pm}\in\mathbb{R}$ belong to the superradiant phase (SP) and explicitly depend on the system size $j$.
L000285	
L000286	By evaluating the Hamiltonian of Eq.~\eqref{eq:DickeSqueezedStates} with the extreme values $ \mathbf{x}_{m}=\mathbf{x}_{0,\pm}$ [Eqs.~\eqref{eq:ExtremeValuesNP}-\eqref{eq:ExtremeValuesSPm}], we find the ground-state energy $E_{0}=j \, h_{\text{D}}(\mathbf{x}_{m})$ presented in Eq.~(5) in the main text. The last result agrees with the description of the Holstein-Primakoff transformation presented in Ref.~\cite{Garbe2017}. Moreover, the expectation values of operators $\hat{a}^{\dagger}\hat{a}$ and $\hat{J}_{z}$ under the squeezed vacuum states provide the expressions
L000287	\begin{align}
L000288	   \langle\mathbf{x}|\hat{a}^{\dagger}\hat{a}|\mathbf{x}\rangle & = \langle\beta|\otimes\langle\xi|\hat{a}^{\dagger}\hat{a}|\xi\rangle\otimes|\beta\rangle = \frac{j}{2}\left(q^{2}+p^{2}\right) , \\
L000289	   \frac{\langle\mathbf{x}|\hat{J}_{z}|\mathbf{x}\rangle}{j} & = \frac{1}{j}\langle\beta|\otimes\langle\xi|\hat{J}_{z}|\xi\rangle\otimes|\beta\rangle = \frac{Q^{2}+P^{2}}{2}-1 .
L000290	\end{align}
L000291	By evaluating the last expressions with the extreme values $\mathbf{x}_{m}$, we find the corresponding Eqs.~(6) and~(7) in the main text.
